import { withAuth } from "@workos-inc/authkit-nextjs";
import type { User as AuthKitUser } from "@workos-inc/node";

export type User = {
  id: string;
  email: string;
  name: string;
  createdAt: string;
};

const users: User[] = [
  { id: "1", email: "ada@example.com", name: "Ada", createdAt: "2026-01-04" },
  { id: "2", email: "grace@example.com", name: "Grace", createdAt: "2026-02-11" },
];

export async function listUsers(): Promise<User[]> {
  return users;
}

export async function getUser(id: string): Promise<User | undefined> {
  return users.find((u) => u.id === id);
}

// The signed-in user comes from WorkOS AuthKit's session cookie. The first
// time a given WorkOS user is seen they're upserted into the local list
// above, so they show up next to the seed data instead of only existing in
// WorkOS.
export async function getCurrentUser(): Promise<User | undefined> {
  const { user } = await withAuth();
  if (!user) return undefined;
  return upsertFromAuthKitUser(user);
}

function upsertFromAuthKitUser(authKitUser: AuthKitUser): User {
  const name =
    [authKitUser.firstName, authKitUser.lastName].filter(Boolean).join(" ") ||
    authKitUser.email;

  const existing = users.find((u) => u.id === authKitUser.id);
  if (existing) {
    existing.email = authKitUser.email;
    existing.name = name;
    return existing;
  }

  const created: User = {
    id: authKitUser.id,
    email: authKitUser.email,
    name,
    createdAt: authKitUser.createdAt.slice(0, 10),
  };
  users.push(created);
  return created;
}

